{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Terameprocol absolute oral bioavailability was approximately 2% in a phase 1 trial in patients with recurrent high-grade gliomas, directly supporting F below 20%."
    },
    {
      "card_ids": ["C15"],
      "claim": "Ganciclovir (DHPG) absolute oral bioavailability was 5.4 ± 1.6% in humans after a 500 mg dose, another quantitative human measurement below 20%."
    },
    {
      "card_ids": ["C08"],
      "claim": "Halofantrine had one absolute estimate of approximately 30% in fasted humans, but multiple other human reports describe low or poor oral bioavailability; this mixed evidence is outweighed by the consistent sub-20% quantitative records."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": ["C08"],
  "decision_summary": "The preponderance of high-transfer evidence, including direct absolute human F measurements of approximately 2%, 5.4%, 10%, 12.5%, and 14.8%, supports F < 20%; one mixed halofantrine estimate of ~30% does not overturn this.",
  "evidence_gaps": [
    "Most records are for other compounds; transferability is inferred from assay-transfer scores rather than direct query measurements.",
    "Halofantrine evidence is mixed, with one absolute estimate of ~30% based on retrospective separate oral and intravenous studies."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C02", "C15"],
  "revision_action": "initial",
  "supportive_card_ids": ["C02", "C15"]
}

